#include <iostream>
#include <string>
using namespace std;

//위임 생성자 활용과 생성자 초기화 리스트 
class Member {
private:
  string id; //아이디
  string pw; //패스워드
public:
  Member();
  Member(string id, string pw);
  Member(string id);
  ~Member(); //소멸자
  bool isCheck() const;
  void disPlay() const;
};

Member::Member() : Member{"null", "null"} { }  
Member::Member(string i, string p) : id{ i }, pw{ p } { } 
Member::Member(string i) : id{i}{
  cout << "매개변수가 하나인 Member 생성자 입니다" << endl;
  cout << "pw 입력 >> ";
  cin >> pw;
}

Member::~Member(){
  cout << id<< "Member객체를 해제 합니다" << endl;
}

bool Member::isCheck() const{
  if (id == pw)
    return false;
  else
    return true;
}

void Member::disPlay() const{
  cout << "id >> " + id << endl;
  cout << "pw >> " + pw << endl << endl;
}

int main() {
  Member mem{};
  Member mem1{ "C++", "C++" }; 
  Member mem2{"Java1"};
  mem.disPlay();
  mem1.disPlay();
  if (mem1.isCheck())
    cout << "사용 가능한 pw 입니다" << endl;
  else
    cout << "id와 동일한 pw는 사용할 수 없습니다" << endl;
  mem2.disPlay();
  return 0;
}

