#include <iostream>
#include <iomanip>
#include <string>
#include <ctime>
#include <random>
#include <memory>
using namespace std;

void message(string msg, int &size){
  cout<<msg<<" 로 생성하는 배열(double) 크기를 입력하세요 >> ";
  cin >> size;
  cout<<size<<endl;
}

inline void elem(int i, double value){
   cout << i + 1 << " ] " << fixed << setprecision(2) << value << endl;
}
int main()
{
  int size;
  unique_ptr<double[]> darray = nullptr;
  double *dptr = nullptr;

  mt19937 gen(time(nullptr));
  uniform_real_distribution<double> rd(10.0, 20.0);

  message("스마트포인터", size);
  darray = make_unique<double[]>(size);
  for (auto i = 0; i < size; i++)
  {
    darray[i] = rd(gen);
    elem(i, darray[i]);

  }

  message("new 연산자", size);
  dptr = new double[size];
  for (auto i = 0; i < size; i++)
  {
    dptr[i] = rd(gen);
     elem(i, dptr[i]);
  }

  cout << endl;
  return 0;
}
